ALTER TABLE users ADD COLUMN is_super_admin boolean NOT NULL DEFAULT false;
ALTER TABLE users ADD COLUMN access_version integer NOT NULL DEFAULT 1;
UPDATE users SET is_super_admin=true WHERE role='admin';
CREATE TABLE access_permissions (key text PRIMARY KEY,label text NOT NULL,group_name text NOT NULL,read_only boolean NOT NULL);
CREATE TABLE access_roles (id uuid PRIMARY KEY,key text NOT NULL UNIQUE,name text NOT NULL UNIQUE,is_system boolean NOT NULL DEFAULT false,version integer NOT NULL DEFAULT 1);
CREATE TABLE access_role_permissions (role_id uuid NOT NULL REFERENCES access_roles(id) ON DELETE CASCADE,permission text NOT NULL REFERENCES access_permissions(key),PRIMARY KEY(role_id,permission));
CREATE TABLE access_user_roles (user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,role_id uuid NOT NULL REFERENCES access_roles(id),PRIMARY KEY(user_id,role_id));
CREATE TABLE access_user_grants (user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,permission text NOT NULL REFERENCES access_permissions(key),PRIMARY KEY(user_id,permission));
CREATE TABLE access_teams (id uuid PRIMARY KEY,name text NOT NULL UNIQUE,version integer NOT NULL DEFAULT 1);
CREATE TABLE access_team_roles (team_id uuid NOT NULL REFERENCES access_teams(id) ON DELETE CASCADE,role_id uuid NOT NULL REFERENCES access_roles(id),PRIMARY KEY(team_id,role_id));
CREATE TABLE access_team_grants (team_id uuid NOT NULL REFERENCES access_teams(id) ON DELETE CASCADE,permission text NOT NULL REFERENCES access_permissions(key),PRIMARY KEY(team_id,permission));
CREATE TABLE access_team_members (team_id uuid NOT NULL REFERENCES access_teams(id) ON DELETE CASCADE,user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,PRIMARY KEY(team_id,user_id));
CREATE INDEX access_member_user_idx ON access_team_members(user_id);

